head.b:skin:
:root { --bg: #0a0f1a; --card: #0f172a; --accent: #1e40af; --accent-light: #3b82f6; --text: #f8fafc; --muted: #94a3b8; --border: #1e293b; }
html { scroll-behavior: smooth; scroll-padding-top: 5.5rem; }
body { font-family: 'Plus Jakarta Sans', sans-serif; margin: 0; padding: 0; background: var(--bg); color: var(--text); line-height: 1.6; background-image: radial-gradient(ellipse 100% 70% at 50% -15%, rgba(30,64,175,0.22), transparent 55%); background-attachment: fixed; }
.inoxup-container { max-width: 1200px; margin: 0 auto; padding: 0 2rem; }
.inoxup-navbar { position: fixed; top: 0; left: 0; right: 0; z-index: 100; padding: 1rem 2rem; background: rgba(10,10,15,0.95); backdrop-filter: blur(12px); border-bottom: 1px solid var(--border); display: flex; align-items: center; justify-content: space-between; }
.inoxup-logo { display: flex; align-items: center; gap: 0.75rem; font-size: 1.25rem; font-weight: 700; color: var(--text); text-decoration: none; }
.inoxup-logo-badge { width: 48px; height: 48px; border-radius: 12px; background: linear-gradient(145deg, #1e3a8a, #2563eb); display: flex; flex-direction: column; align-items: center; justify-content: center; flex-shrink: 0; box-shadow: 0 4px 16px rgba(37,99,235,0.45); border: 1px solid rgba(96,165,250,0.5); }
.inoxup-logo-badge-i { font-size: 0.65rem; font-weight: 800; letter-spacing: 0.12em; color: #fff; line-height: 1; }
.inoxup-logo-badge-u { font-size: 0.75rem; font-weight: 800; color: #bfdbfe; line-height: 1; margin-top: 2px; }
.inoxup-logo-badge--hero { width: 120px; height: 120px; border-radius: 24px; margin: 0 auto 1.25rem; }
.inoxup-logo-badge--hero .inoxup-logo-badge-i { font-size: 1rem; letter-spacing: 0.15em; }
.inoxup-logo-badge--hero .inoxup-logo-badge-u { font-size: 1.15rem; margin-top: 4px; }
.inoxup-logo-wordmark { font-weight: 700; letter-spacing: 0.05em; }
.inoxup-social-wall { display: grid; grid-template-columns: 1fr; gap: 2rem; margin-bottom: 2.5rem; max-width: 900px; margin-left: auto; margin-right: auto; }
@media (min-width: 960px) { .inoxup-social-wall { grid-template-columns: 1fr 1fr; max-width: 1100px; align-items: start; } }
.inoxup-social-box { background: var(--card); border: 1px solid var(--border); border-radius: 16px; padding: 1.25rem; box-shadow: 0 8px 32px rgba(0,0,0,0.2); }
.inoxup-social-box h3 { margin: 0 0 0.75rem; font-size: 1.1rem; color: var(--text); text-align: center; }
.inoxup-fb-frame { width: 100%; max-width: 500px; margin: 0 auto; border-radius: 12px; overflow: hidden; border: 1px solid var(--border); min-height: 480px; background: #fff; }
.inoxup-fb-frame iframe { display: block; width: 100%; border: 0; min-height: 480px; }
.inoxup-ig-lead { color: var(--muted); font-size: 0.95rem; text-align: center; margin: 0 0 1rem; line-height: 1.5; }
.inoxup-social-box .inoxup-btn-ig { width: 100%; justify-content: center; box-sizing: border-box; }
.inoxup-nav-links { display: flex; gap: 2rem; }
.inoxup-nav-links a { color: var(--muted); text-decoration: none; font-weight: 500; }
.inoxup-nav-links a:hover { color: var(--accent-light); }
.inoxup-btn { display: inline-block; padding: 0.6rem 1.25rem; border-radius: 10px; font-weight: 600; text-decoration: none; background: var(--accent); color: white; }
.inoxup-btn:hover { background: var(--accent-light); opacity: 1; }
.inoxup-hero { min-height: 100vh; display: flex; align-items: center; justify-content: center; text-align: center; padding: 8rem 2rem 4rem; background: radial-gradient(ellipse 90% 55% at 50% 20%, rgba(59,130,246,0.08), transparent 60%); }
.inoxup-hero h1 { font-size: clamp(2.5rem, 5vw, 3.5rem); font-weight: 700; margin-bottom: 1rem; letter-spacing: 0.05em; }
.inoxup-hero .inoxup-tagline { font-size: 1rem; color: var(--accent-light); margin-bottom: 0.5rem; }
.inoxup-hero p:not(.inoxup-tagline) { font-size: 1.1rem; color: var(--muted); margin-bottom: 1.5rem; max-width: 600px; margin-left: auto; margin-right: auto; }
.inoxup-section { padding: 5rem 0; }
.inoxup-section-title { text-align: center; margin-bottom: 3rem; }
.inoxup-section-title h2 { font-size: 2rem; font-weight: 700; margin-bottom: 0.5rem; }
.inoxup-section-title p { color: var(--muted); }
.inoxup-official-links { text-align: center; margin: 0 auto 2rem; max-width: 42rem; padding: 0 0.5rem; }
.inoxup-official-links .inoxup-official-lead { color: var(--text); margin: 0 0 0.75rem; font-size: 1.05rem; font-weight: 600; }
.inoxup-official-links .inoxup-official-sub { color: var(--muted); margin: 0 0 1rem; font-size: 0.95rem; line-height: 1.5; }
.inoxup-official-btns { display: flex; gap: 0.75rem; justify-content: center; flex-wrap: wrap; margin-bottom: 1rem; }
.inoxup-official-hint { font-size: 0.82rem; color: var(--muted); line-height: 1.55; margin: 0; padding: 0.75rem 1rem; background: rgba(15,23,42,0.6); border-radius: 12px; border: 1px solid var(--border); text-align: left; }
.inoxup-work-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 2rem; }
.inoxup-work-card { background: var(--card); border: 1px solid var(--border); border-radius: 16px; padding: 2rem; box-shadow: 0 4px 24px rgba(0,0,0,0.25); }
.inoxup-work-card:hover { border-color: var(--accent); }
.inoxup-work-card h3 { font-size: 1.25rem; margin-bottom: 0.75rem; color: var(--accent-light); }
.inoxup-work-card p { color: var(--muted); }
.inoxup-services-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(250px, 1fr)); gap: 1.5rem; }
.inoxup-service-card { background: var(--card); border: 1px solid var(--border); border-radius: 16px; padding: 2rem; text-align: center; box-shadow: 0 4px 24px rgba(0,0,0,0.25); }
.inoxup-service-card:hover { border-color: var(--accent); }
.inoxup-service-icon { display: flex; align-items: center; justify-content: center; margin-bottom: 1rem; color: var(--accent-light); }
.inoxup-service-icon svg { width: 2.5rem; height: 2.5rem; flex-shrink: 0; }
.inoxup-ico { display: inline-block; vertical-align: middle; flex-shrink: 0; }
.inoxup-btn .inoxup-ico, .inoxup-btn-whatsapp .inoxup-ico, .inoxup-btn-phone .inoxup-ico, .inoxup-btn-ig .inoxup-ico, .inoxup-btn-fb .inoxup-ico { width: 1.15em; height: 1.15em; margin-right: 0.4rem; }
.inoxup-float-whatsapp svg { width: 28px; height: 28px; display: block; }
.inoxup-gallery { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 1.5rem; }
.inoxup-gallery-item { aspect-ratio: 16/10; border-radius: 16px; overflow: hidden; border: 1px solid var(--border); background: #1e293b; box-shadow: 0 6px 28px rgba(0,0,0,0.35); transition: transform 0.22s ease, box-shadow 0.22s ease; }
.inoxup-gallery-item:hover { transform: translateY(-4px); box-shadow: 0 14px 40px rgba(30,64,175,0.18); border-color: rgba(59,130,246,0.45); }
.inoxup-gallery-item img { width: 100%; height: 100%; object-fit: cover; display: block; }
.inoxup-video-wrapper { position: relative; padding-bottom: 56.25%; height: 0; overflow: hidden; border-radius: 16px; background: #000; }
.inoxup-video-wrapper iframe { position: absolute; top: 0; left: 0; width: 100%; height: 100%; border: 0; }
.inoxup-embed-note { max-width: 720px; margin: 1rem auto 0; padding: 1rem 1.25rem; font-size: 0.9rem; color: var(--muted); border: 1px dashed var(--border); border-radius: 12px; text-align: left; line-height: 1.5; }
.inoxup-info-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 1rem; }
.inoxup-info-card { background: var(--card); border: 1px solid var(--border); border-radius: 12px; padding: 1.5rem; text-align: center; }
.inoxup-info-card strong { display: block; font-size: 1.25rem; color: var(--accent-light); }
.inoxup-info-card span { color: var(--muted); font-size: 0.9rem; }
.inoxup-footer { padding: 2rem; border-top: 1px solid var(--border); text-align: center; }
.inoxup-footer a { color: var(--accent-light); text-decoration: none; }
.inoxup-footer-copy { color: var(--muted); font-size: 0.85rem; margin-top: 1rem; }
.inoxup-contact-btns { display: flex; gap: 1rem; justify-content: center; flex-wrap: wrap; margin: 1.5rem 0; }
.inoxup-btn-whatsapp { background: #25D366 !important; color: white !important; display: inline-flex; align-items: center; gap: 0.5rem; padding: 0.75rem 1.5rem; border-radius: 12px; font-weight: 600; text-decoration: none; }
.inoxup-btn-whatsapp:hover { background: #20bd5a !important; opacity: 1; }
.inoxup-btn-phone { background: var(--accent); color: white; display: inline-flex; align-items: center; gap: 0.5rem; padding: 0.75rem 1.5rem; border-radius: 12px; font-weight: 600; text-decoration: none; }
.inoxup-btn-fb { background: #1877f2; color: white; display: inline-flex; align-items: center; gap: 0.5rem; padding: 0.75rem 1.5rem; border-radius: 12px; font-weight: 600; text-decoration: none; }
.inoxup-btn-ig { background: linear-gradient(45deg, #f09433, #e6683c, #dc2743, #cc2366, #bc1888); color: white; display: inline-flex; align-items: center; gap: 0.5rem; padding: 0.75rem 1.5rem; border-radius: 12px; font-weight: 600; text-decoration: none; }
.inoxup-float-whatsapp { position: fixed; bottom: 24px; right: 24px; z-index: 999; width: 60px; height: 60px; border-radius: 50%; background: #25D366; color: white; display: flex; align-items: center; justify-content: center; text-decoration: none; box-shadow: 0 4px 20px rgba(37,211,102,0.5); }
.inoxup-float-whatsapp:hover { background: #20bd5a; transform: scale(1.05); }
.inoxup-mnav-cb { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); border: 0; }
.inoxup-mnav-btn { display: none; align-items: center; justify-content: center; padding: 0.45rem 0.6rem; color: var(--text); cursor: pointer; border-radius: 8px; border: 1px solid var(--border); background: var(--card); }
.inoxup-mnav-btn:hover { border-color: var(--accent-light); color: var(--accent-light); }
@media (max-width: 900px) {
  body { background-attachment: scroll; }
  .inoxup-navbar { flex-wrap: wrap; gap: 0.75rem; align-items: center; padding: 0.75rem 1rem; }
  .inoxup-mnav-btn { display: flex; order: 2; margin-left: auto; }
  .inoxup-navbar > a.inoxup-btn { order: 3; font-size: 0.8rem; padding: 0.45rem 0.65rem; }
  .inoxup-nav-links { display: none; width: 100%; order: 10; flex-direction: column; gap: 0; padding: 0.75rem 0 0; border-top: 1px solid var(--border); margin-top: 0.25rem; }
  .inoxup-nav-links a { padding: 0.65rem 0; border-bottom: 1px solid var(--border); }
  .inoxup-nav-links a:last-child { border-bottom: none; }
  #inoxup-mnav:checked ~ .inoxup-nav-links { display: flex; }
}
#main, .main-inner { background: var(--bg); color: var(--text); }
.main-inner .column-center-inner { max-width: 1200px; margin: 0 auto; padding: 2rem 1.5rem 4rem; }
.blog-posts .post { background: var(--card); border: 1px solid var(--border); border-radius: 16px; padding: 1.75rem; margin-bottom: 1.5rem; }
.blog-posts .post-title a, .blog-posts h3.post-title a { color: var(--accent-light); text-decoration: none; }
.blog-posts .post-title a:hover { text-decoration: underline; }
.blog-posts .post-body { color: var(--muted); }
.blog-posts .post-footer, .blog-posts .post-header { color: var(--muted); font-size: 0.9rem; }
.blog-pager { text-align: center; margin: 2rem 0; }
.blog-pager a { color: var(--accent-light); font-weight: 600; text-decoration: none; }
.blog-pager a:hover { text-decoration: underline; }
